from z3 import *

# Create a Z3 solver
s = Solver()

# Variables for edges
E = [[Bool(f"E_{i}_{j}") if i < j else Bool(f"E_{j}_{i}") if i > j else False for j in range(13)] for i in range(13)]

# Variables for colors
C = [Int(f"C_{i}") for i in range(13)]

# Color constraints
for i in range(13):
    s.add(C[i] >= 0, C[i] < 5)

# Edge implies different colors
for i in range(13):
    for j in range(i + 1, 13):
        s.add(Implies(E[i][j], C[i] != C[j]))

# Degree constraints
for i in range(13):
    s.add(Sum([If(E[i][j], 1, 0) for j in range(13) if i != j]) >= 4)

# Known edges
known_edges = [(1,3), (2,7), (3,11), (3,10), (0,12), (2,10), (2,4), (1,11)]
for u, v in known_edges:
    if u > v:
        u, v = v, u
    s.add(E[u][v] == True)

# Solve
if s.check() == sat:
    m = s.model()
    edges = []
    for i in range(13):
        for j in range(i + 1, 13):
            if is_true(m[E[i][j]]):
                edges.append((i, j))
    print("SAT")
    print(edges)
else:
    print("UNSAT")
